const float PI=3.14159265359;const float TAU=6.28318530718;
float sat(float x){return clamp(x,0.,1.);}vec2 rot(vec2 q,float a){float c=cos(a),s=sin(a);return mat2(c,-s,s,c)*q;}
float fill(float d,float s){return 1.-smoothstep(0.,max(s,.0001),d);}float line(float d,float w,float s){return 1.-smoothstep(w,w+max(s,.0001),abs(d));}
float hash21(vec2 p){p=fract(p*vec2(.1031,.11369));p+=dot(p,p.yx+19.19);return fract(p.x*p.y*(p.x+p.y));}
