float simplex(vec2 p){float f=(sqrt(3.)-1.)*.5,g=(3.-sqrt(3.))/6.;vec2 i=floor(p+dot(p,vec2(f)));vec2 a=p-i+dot(i,vec2(g));vec2 j=a.x>a.y?vec2(1,0):vec2(0,1);vec2 b=a-j+g,c=a-1.+2.*g;vec3 w=max(vec3(.5-dot(a,a),.5-dot(b,b),.5-dot(c,c)),vec3(0));w*=w;w*=w;return 70.*dot(w,vec3(dot(grad(i),a),dot(grad(i+j),b),dot(grad(i+1.),c)));}
float fbm(vec2 p){float v=0.,w=.5;for(int i=0;i<5;i++){v+=w*noise(p);p=rot(p,.47)*2.03+13.7;w*=.5;}return v/ .96875;}
float fractalValue(vec2 p,int octaves,float gain){float v=0.,w=1.,sum=0.;for(int i=0;i<8;i++){if(i>=octaves)break;v+=w*noise(p);sum+=w;p=rot(p,.47)*2.03+13.7;w*=gain;}return v/max(sum,.00001);}
float checker(vec2 u,float count,float soft){vec2 p=u*count,f=fract(p);float c=mod(floor(p.x)+floor(p.y),2.);float edge=min(min(f.x,1.-f.x),min(f.y,1.-f.y));return mix(.5,c,smoothstep(0.,max(soft,.00001),edge));}
float brick(vec2 u,float columns,float rows,float mortar,float offset,float soft){vec2 p=u*vec2(columns,rows);float row=floor(p.y);p.x+=mod(row,2.)*offset;vec2 f=fract(p),distance=min(f,1.-f);float edge=min(distance.x,distance.y);return smoothstep(mortar*.5,mortar*.5+max(soft,.00001),edge);}
float turb(vec2 p){float v=0.,w=.5;for(int i=0;i<5;i++){v+=w*abs(perlin(p));p=rot(p,.31)*2.1+11.;w*=.5;}return sat(v*1.5);}
vec3 voronoi(vec2 p,float seed){vec2 i=floor(p),f=fract(p);float a=10.,b=10.,id=0.;for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){vec2 o=vec2(x,y),h=vec2(hash21(i+o+seed),hash21(i+o+seed+9.));float d=length(o+h-f);if(d<a){b=a;a=d;id=hash21(i+o+seed);}else b=min(b,d);}return vec3(a,b-a,id);}
vec2 curl(vec2 q){float e=.04;return vec2(fbm(q+vec2(0,e))-fbm(q-vec2(0,e)),-fbm(q+vec2(e,0))+fbm(q-vec2(e,0)))/(2.*e);}
float box(vec2 p,vec2 b,float r){vec2 d=abs(p)-b+r;return length(max(d,0.))+min(max(d.x,d.y),0.)-r;}
float poly(vec2 q,float n,float r){n=max(3.,floor(n));float a=atan(q.y,q.x),sector=TAU/n;return cos(floor(.5+a/sector)*sector-a)*length(q)-r;}
float segment(vec2 p,vec2 a,vec2 b){vec2 q=p-a,v=b-a;return length(q-v*clamp(dot(q,v)/max(dot(v,v),.00001),0.,1.));}
float starDistance(vec2 p,float count,float radius,float ratio,float rounding){float corner=min(rounding,radius*.45),r=radius-corner,halfAngle=PI/count;float angle=abs(mod(atan(p.x,p.y)+halfAngle,2.*halfAngle)-halfAngle);vec2 q=length(p)*vec2(sin(angle),cos(angle));vec2 a=vec2(0,r),b=r*ratio*vec2(sin(halfAngle),cos(halfAngle)),edge=b-a;float side=dot(q-a,vec2(-edge.y,edge.x));return segment(q,a,b)*(side>0.?1.:-1.)-corner;}
