float profileShape(vec2 p,float r,float w,float power,float bend,float skew,int leaf){float distance=10.;vec2 left=profilePoint(0.,-1.,r,w,power,bend,skew,leaf),right=profilePoint(0.,1.,r,w,power,bend,skew,leaf);for(int j=1;j<=32;j++){float t=float(j)/32.;vec2 l=profilePoint(t,-1.,r,w,power,bend,skew,leaf),h=profilePoint(t,1.,r,w,power,bend,skew,leaf);distance=min(distance,min(segment(p,left,l),segment(p,right,h)));left=l;right=h;}float phase=acos(clamp(-p.y/r,-1.,1.))/PI*32.;float cell=min(floor(phase),31.);float y0=profilePoint(cell/32.,-1.,r,w,power,bend,skew,leaf).y,y1=profilePoint((cell+1.)/32.,-1.,r,w,power,bend,skew,leaf).y;float f=clamp((p.y-y0)/max(y1-y0,.0000001),0.,1.);float lo=mix(profilePoint(cell/32.,-1.,r,w,power,bend,skew,leaf).x,profilePoint((cell+1.)/32.,-1.,r,w,power,bend,skew,leaf).x,f),hi=mix(profilePoint(cell/32.,1.,r,w,power,bend,skew,leaf).x,profilePoint((cell+1.)/32.,1.,r,w,power,bend,skew,leaf).x,f);return abs(p.y)<=r&&p.x>=lo&&p.x<=hi?-distance:distance;}
vec2 cubicPoint(vec4 a,vec4 b,float t){float s=1.-t;return s*s*s*a.xy+3.*s*s*t*a.zw+3.*s*t*t*b.xy+t*t*t*b.zw;}
vec2 cubicTangent(vec4 a,vec4 b,float t){float s=1.-t;return 3.*s*s*(a.zw-a.xy)+6.*s*t*(b.xy-a.zw)+3.*t*t*(b.zw-b.xy);}
float ribbonShape(vec2 p,vec4 a,vec4 b,vec4 c,vec4 d){if(c.w<=0.)return 0.;float distance=10.,nearest=0.;vec2 start=a.xy,previous=start;float before=0.;for(int j=1;j<=48;j++){float t=float(j)/48.*c.w;vec2 next=cubicPoint(a,b,t),v=next-previous;float h=clamp(dot(p-previous,v)/max(dot(v,v),.0000001),0.,1.);float at=mix(before,t,h),candidate=length(p-previous-v*h)-mix(c.x,c.y,at)*.5;if(candidate<distance){distance=candidate;nearest=at;}previous=next;before=t;}if(d.x>.5){vec2 first=cubicTangent(a,b,0.),last=cubicTangent(a,b,c.w);if(nearest<.000001)distance=max(distance,-dot(p-start,normalize(first+vec2(.000001,0))));if(nearest>c.w-.000001)distance=max(distance,dot(p-previous,normalize(last+vec2(.000001,0))));}return fill(distance,c.z);}
