float gearRadius(float a,float n,float radius,float depth,float width,float top){float sector=TAU/n;float beta=abs(mod(a,sector)-sector*.5);float halfAngle=PI*width/n;float root=max(radius-depth,.001);if(beta>=halfAngle)return root;float topAngle=halfAngle*top;vec2 base=root*vec2(sin(halfAngle),cos(halfAngle));vec2 tip=radius*vec2(sin(topAngle),cos(topAngle));if(beta<=topAngle)return max(root,tip.y/cos(beta));vec2 edge=tip-base;vec2 ray=vec2(sin(beta),cos(beta));return max(root,(base.x*edge.y-base.y*edge.x)/max(ray.x*edge.y-ray.y*edge.x,.000001));}
