float grid(vec2 p,float w,float s){vec2 d=abs(fract(p)-.5);return line(max(d.x,d.y)-.5,w,s);}
vec2 hexcell(vec2 p){p*=vec2(1.,1.7320508);vec2 a=mod(p,vec2(1.,1.7320508))-.5*vec2(1.,1.7320508),b=mod(p-.5*vec2(1.,1.7320508),vec2(1.,1.7320508))-.5*vec2(1.,1.7320508);vec2 q=dot(a,a)<dot(b,b)?a:b;return vec2(abs(max(abs(q.x),abs(q.x)*.5+abs(q.y)*.8660254)-.5),length(q));}
float spots(vec2 p,float radius,float soft){vec2 i=floor(p),f=fract(p);float v=0.;for(int y=-1;y<=1;y++)for(int x=-1;x<=1;x++){vec2 o=vec2(x,y);vec2 c=vec2(hash21(i+o),hash21(i+o+37.));v=max(v,fill(length(f-o-c)-radius*(.3+.7*hash21(i+o+4.)),soft));}return v;}
float metaball(vec2 q,float r,float t){float sum=0.;for(int i=0;i<5;i++){float a=float(i)*TAU/5.+t;vec2 c=vec2(cos(a),sin(a*1.3))*r*.5;sum+=r*r*.04/max(dot(q-c,q-c),.003);}return smoothstep(.9,1.1,sum);}
