float circuit(vec2 p,float w,float s,float h){vec2 i=floor(p),q=fract(p)-.5;float v=line(q.x,w,s)*fill(q.y,s);if(hash21(i+h)>.5)v=max(v,line(q.y,w,s));return max(v,line(length(q)-.14,w,s));}
float fibonacci(vec2 q,int count,float r,float w,float s){float v=0.;for(int i=0;i<256;i++){if(i>=count)break;float n=float(i);vec2 c=r*sqrt((n+.5)/float(count))*vec2(cos(n*2.39996323),sin(n*2.39996323));v=max(v,fill(length(q-c)-w,s));}return v;}
float sierpinski(vec2 p,int n){float v=1.;p*=float(n);for(int i=0;i<6;i++){if(mod(floor(p.x)+floor(p.y),2.)>0.5)v=0.;p*=.5;}return v;}
