float flame(vec2 q,float r,float n,float k,float t,float h){float height=sat((q.y+r)/(2.*r));float warp=(fbm(q*n+vec2(0.,-t*2.)+h)-.5)*k;return pow(sat(1.-abs(q.x+warp)/(r*max(.03,1.-height))),1.5)*sat(height*4.)*pow(1.-height,.5)*(.5+.5*fbm(q*n+vec2(0.,-t)+h));}
