float ribbon(vec2 q,float r,float w,float n,float d,float k,float t,float h,int mode){float y=sat((q.y+1.)*.5),x=q.x;float width=r*.4;float base=exp(-abs(x)/(width+.001))*pow(y,.5+d*3.);if(mode==1)return fill(abs(x)-width*y,.02)*y;
